const introEmpty:Introduction={bio:'',signature:'',readme:''};
function memberFromInput(value:string):number|null {
  const input=value.trim();if(/^[1-9]\d{0,14}$/.test(input)&&Number.isSafeInteger(Number(input)))return Number(input);
  try{const url=new URL(input),id=url.pathname.match(/^\/space\/([1-9]\d{0,14})\/?$/)?.[1];if(url.protocol==='https:'&&['www.nodeseek.com','nodeseek.com'].includes(url.hostname)&&!url.username&&!url.password&&!url.port&&id&&Number.isSafeInteger(Number(id)))return Number(id);}catch{}
  return null;
}
