  useEffect(()=>{if(!loaded||!account.id)return;const timer=setTimeout(()=>void window.seekdesk.saveDraft(draftKey,{title,content,category,rank,imageWidths:widths},account.id).catch(error=>onNotify(errorMessage(error),'error')),600);return()=>clearTimeout(timer);},[title,content,category,rank,widths,draftKey,loaded,account.id]);
  if(account.status!=='signed-in')return <LoginPrompt onLogin={onLogin}/>;
  const publish=async(confirmed=false)=>{if(busy)return;setBusy(true);try{const prepared=await window.seekdesk.prepareImages(content,widths);const result=await window.seekdesk.writeForum(source?{kind:'edit',url:source.url,floor:source.floor,title,content:prepared}:{kind:'new-topic',title,content:prepared,category,rank,confirmed},account.id!);if(result.confirmation){setConfirmation(result.confirmation);return;}onNotify(result.message,'success');await window.seekdesk.saveDraft(draftKey,null,account.id);setLoaded(false);setContent('');setTitle('');if(result.url)onPublished(toPost({id:String(result.postId||result.url.match(/post-(\d+)/)?.[1]||''),url:result.url,title:title||'帖子'}));else onBack();}catch(error){onNotify(errorMessage(error),'error');}finally{setBusy(false);}};
