export function RankingPanel({period='realtime',showScore=false,refreshSeconds=180,onOpenPost,onBack}:{period?:RankingPeriod;showScore?:boolean;refreshSeconds?:number;onOpenPost:OpenPost;onBack:()=>void}) {
  const [selected,setSelected]=useState(period),[result,setResult]=useState<RankingResult|null>(null),[loading,setLoading]=useState(false),[error,setError]=useState('');
  const request=useRef(0);
  const reload=useCallback(async(force=false)=>{const revision=++request.current;setLoading(true);setError('');try{const value=await window.seekdesk.getHotRanking(selected,force);if(revision===request.current){setResult(value);setError(value.error||'');}}catch(error){if(revision===request.current)setError(errorMessage(error));}finally{if(revision===request.current)setLoading(false);}},[selected]);
  useEffect(()=>{void reload();const timer=setInterval(()=>void reload(),Math.max(60,Math.min(1800,refreshSeconds))*1000);return()=>{request.current++;clearInterval(timer);};},[reload,refreshSeconds]);
  return <section className="full-page ranking-page"><PageHeading title="NodeSeek 热榜" onBack={onBack}><IconButton label="刷新热榜" onClick={()=>void reload(true)}><RefreshCw size={18}/></IconButton></PageHeading><div className="section-tabs">{([['realtime','实时'],['daily','日榜'],['weekly','周榜']] as const).map(([id,label])=><button key={id} className={selected===id?'selected':''} onClick={()=>setSelected(id)}>{label}</button>)}</div><div className="page-scroll">{loading&&!result?<Loading/>:error&&!result?<ErrorState error={error} onRetry={()=>void reload()}/>:<>{error&&<ErrorState error={error} onRetry={()=>void reload()}/>}<div className="ranking-full">{result?.items.map(item=><RankingRow key={item.id} item={item} showScore={showScore} onClick={()=>onOpenPost(toPost(item))}/>)}{!result?.items.length&&<Empty>当前没有热榜内容</Empty>}</div><footer className="ranking-footer"><time dateTime={result?.fetchedAt}>更新 {result?.fetchedAt?new Date(result.fetchedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—'}</time><span className="ranking-count">共 {result?.items.length||0} 条</span></footer></>}</div></section>;
}
export function RankingRow({item,showScore=false,onClick}:{item:RankingItem;showScore?:boolean;onClick:()=>void}) {return <button className="ranking-row" onClick={onClick}><span className={`ranking-position top-${item.position}`} aria-label={`第 ${item.position} 名`}>{item.position<=3&&<Flame size={13} aria-hidden="true"/>}<span>{String(item.position).padStart(2,'0')}</span></span><strong className="ranking-title">{item.title}</strong>{showScore&&item.score!==undefined&&<small className="ranking-score">{item.score}</small>}</button>;}

export function RulingsDialog({member,onClose}:{member:{id:number;name:string};onClose:()=>void}) {
  const [result,setResult]=useState<Awaited<ReturnType<Window['seekdesk']['queryRulings']>>|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(true),[retry,setRetry]=useState(0);
  useEffect(()=>{let current=true;setLoading(true);setError('');void window.seekdesk.queryRulings(member.id,member.name).then(value=>{if(current)setResult(value);}).catch(reason=>{if(current)setError(errorMessage(reason));}).finally(()=>{if(current)setLoading(false);});return()=>{current=false;};},[member.id,member.name,retry]);
  return <Modal title={`${member.name} 的管理记录`} onClose={onClose} wide>{loading?<Loading label="正在查询公开管理记录…"/>:error?<ErrorState error={error} onRetry={()=>setRetry(value=>value+1)}/>:<><div className="rulings-list">{result?.records.length?result.records.map(record=><article key={record.id}><strong>{record.action}</strong><p>{record.reason}</p><small>{record.date}{record.operator&&` · ${record.operator}`}</small>{record.url&&<button className="text-button" onClick={()=>void window.seekdesk.openExternal(record.url!)}>查看原记录</button>}</article>):<Empty>未查询到公开管理记录</Empty>}</div><p className="muted">{result?.source} · {result?.fetchedAt?dateLabel(result.fetchedAt,true):''}</p></>}</Modal>;
}

const extensionCards=[{id:'hot',title:'NodeSeek 热榜',icon:'🔥',text:'实时、日榜、周榜与侧栏榜单，可配置刷新和显示。'},{id:'attendance',title:'每日签到',icon:'📅',text:'固定或随机鸡腿，登录后自动签到。'},{id:'office',title:'摸鱼老板键',icon:'💼',text:'一键切换到办公页面，自定义标题与快捷键。'},{id:'value',title:'剩余价值计算器',icon:'🧮',text:'使用 sy.3xme.com 计算剩余价值。'},{id:'block',title:'屏蔽用户',icon:'🙈',text:'按用户名或 UID 屏蔽帖子和回复。'},{id:'authorOnly',title:'只看楼主',icon:'👤',text:'阅读时只显示楼主的内容，保留完整楼层。'},{id:'keywords',title:'关键词监控',icon:'🔔',text:'定时检查新帖并记录关键词命中。'},{id:'rulings',title:'管理记录查询',icon:'⚖️',text:'查询用户的公开管理记录。'}] as const;
export function ExtensionsPanel({account,state,onChange,onBack,onNotify,onOpenRanking,onOpenPost,onMember,initialExtension}:{initialExtension?:ExtensionsState['installed'][number];titleHint?:string;account:AccountState;state:ExtensionsState;onChange:(state:ExtensionsState)=>Promise<void>;onBack:()=>void;onNotify:Notify;onOpenRanking:()=>void;onOpenPost:OpenPost;onMember:(id:number)=>void}) {
  const [tab,setTab]=useState<'installed'|'all'>('installed'),[selected,setSelected]=useState<ExtensionsState['installed'][number]|null>(initialExtension==='value'?null:initialExtension||null),[saving,setSaving]=useState(false),[blockName,setBlockName]=useState(''),[uid,setUid]=useState(''),[rulings,setRulings]=useState<Awaited<ReturnType<Window['seekdesk']['queryRulings']>>|null>(null),[querying,setQuerying]=useState(false),[local,setLocal]=useState(state);
  const original=useRef(state),editSession=useRef(0),saveRequest=useRef(0);
  const selectExtension=(value:ExtensionsState['installed'][number]|null)=>{editSession.current++;original.current=state;setLocal(state);setSelected(value);setSaving(false);};
  useEffect(()=>{if(!selected){original.current=state;setLocal(state);}},[state,selected]);
  useEffect(()=>{if(initialExtension==='value'){selectExtension(null);void window.seekdesk.openCalculator().catch(error=>onNotify(errorMessage(error),'error'));}else if(initialExtension)selectExtension(initialExtension);},[initialExtension]);
  const save=async(value?:ExtensionsState)=>{const next=value||mergeExtensionEdits(state,original.current,local);if(selected==='hot'&&(!Number.isInteger(next.hotSidebarCount)||next.hotSidebarCount<5||next.hotSidebarCount>30)){onNotify('侧栏显示条数应为 5–30 之间的整数。','error');return false;}const session=editSession.current,request=++saveRequest.current;setSaving(true);try{await onChange(next);if(session!==editSession.current||request!==saveRequest.current)return false;if(!value){original.current=next;setLocal(next);}return true;}catch(error){if(session===editSession.current&&request===saveRequest.current)onNotify(errorMessage(error),'error');return false;}finally{if(session===editSession.current&&request===saveRequest.current)setSaving(false);}};
  const toggleInstall=(id:ExtensionsState['installed'][number])=>{const installed=state.installed.includes(id),next={...state,installed:installed?state.installed.filter(value=>value!==id):[...state.installed,id],enabled:installed?state.enabled.filter(value=>value!==id):[...state.enabled,id]};void save(next);};
  const cards=extensionCards.filter(card=>tab==='all'||state.installed.includes(card.id));
  return <section className="full-page extensions-page"><PageHeading title="扩展中心" onBack={onBack}/><div className="section-tabs"><button className={tab==='installed'?'selected':''} onClick={()=>setTab('installed')}>已安装 <small>{state.installed.length}</small></button><button className={tab==='all'?'selected':''} onClick={()=>setTab('all')}>全部 <small>8</small></button></div><div className="page-scroll"><div className="extension-grid">{cards.map(card=><article className="extension-card" key={card.id}><div className="extension-icon">{card.icon}</div><h2>{card.title}</h2><p>{card.text}</p><div className="extension-status">{state.installed.includes(card.id)?<><button role="switch" aria-label={`启用${card.title}`} aria-checked={state.enabled.includes(card.id)} className={`toggle${state.enabled.includes(card.id)?' checked':''}`} disabled={saving} onClick={()=>void save({...state,enabled:state.enabled.includes(card.id)?state.enabled.filter(value=>value!==card.id):[...state.enabled,card.id]})}><span/></button><span>{state.enabled.includes(card.id)?'已启用':'已停用'}</span></>:<span>尚未安装</span>}</div><footer>{state.installed.includes(card.id)?<><button className="text-button" onClick={()=>{if(card.id==='value'){void window.seekdesk.openCalculator().catch(error=>onNotify(errorMessage(error),'error'));return;}selectExtension(card.id);if(card.id==='keywords'&&state.unread)void save({...state,unread:0});}}>{card.id==='value'?'打开计算器':'设置 / 打开'}</button><button className="icon-button" aria-label={`卸载${card.title}`} onClick={()=>toggleInstall(card.id)}><Trash2 size={16}/></button></>:<button className="secondary-button" disabled={saving} onClick={()=>toggleInstall(card.id)}><Plus size={16}/>安装</button>}</footer></article>)}</div>{!cards.length&&<Empty>尚未安装扩展，请切换到“全部”安装。</Empty>}</div>{selected&&<Modal title={extensionCards.find(card=>card.id===selected)!.title} onClose={()=>selectExtension(null)} wide>{selected==='hot'?<div className="hot-ranking-settings">
  <label className="field-label">默认榜单<select aria-label="热榜默认榜单" value={local.hotDefaultPeriod||'realtime'} onChange={event=>setLocal({...local,hotDefaultPeriod:event.target.value as RankingPeriod})}><option value="realtime">实时榜</option><option value="daily">日榜</option><option value="weekly">周榜</option></select></label>
  <label className="field-label">侧栏显示条数<input type="number" min={5} max={30} step={1} aria-label="热榜侧栏显示条数" value={local.hotSidebarCount??10} onChange={event=>setLocal({...local,hotSidebarCount:Number(event.target.value)})}/></label>
  <label className="field-label">自动刷新间隔<select aria-label="热榜自动刷新间隔" value={local.hotRefreshSeconds??180} onChange={event=>setLocal({...local,hotRefreshSeconds:Number(event.target.value)})}>{[[60,'1 分钟'],[120,'2 分钟'],[180,'3 分钟'],[300,'5 分钟'],[600,'10 分钟'],[900,'15 分钟'],[1800,'30 分钟']].map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>
  <SettingCheck label="显示热度分值" checked={local.hotShowScore===true} onChange={value=>setLocal({...local,hotShowScore:value})}/>
  <button className="secondary-button" onClick={()=>{selectExtension(null);onOpenRanking();}}>打开完整热榜<ArrowRight size={16}/></button>
</div>:selected==='attendance'?<><div className="setting-row"><strong>签到模式</strong><select value={local.attendanceMode} onChange={event=>setLocal({...local,attendanceMode:event.target.value as 'fixed'|'random'})}><option value="fixed">固定鸡腿</option><option value="random">随机鸡腿</option></select></div><SettingCheck label="登录后自动签到" checked={local.autoAttendance} onChange={value=>setLocal({...local,autoAttendance:value})}/>{state.attendance&&<p>{state.attendance.message||state.attendance.kind}{state.attendance.gain!==undefined&&` · +${state.attendance.gain} 鸡腿`}</p>}<button className="secondary-button" disabled={!account.id} onClick={()=>void window.seekdesk.writeForum({kind:'attendance',mode:local.attendanceMode},account.id!).then(result=>onNotify(result.message,result.attendance?.kind==='completed'||result.attendance?.kind==='alreadyCompleted'?'success':'error')).catch(error=>onNotify(errorMessage(error),'error'))}>立即签到</button></>:selected==='office'?<><label className="field-label">办公页标题<input value={local.officeTitle} onChange={event=>setLocal({...local,officeTitle:event.target.value})}/></label><label className="field-label">返回按钮文字<input value={local.officeButton} onChange={event=>setLocal({...local,officeButton:event.target.value})}/></label><label className="field-label">Ctrl + Shift + 快捷键<input maxLength={1} value={local.officeKey} onChange={event=>setLocal({...local,officeKey:event.target.value})} placeholder="字母或数字，例如 9（Ctrl + Shift + 9）"/></label><button className="secondary-button" onClick={()=>void window.seekdesk.toggleBossKey().catch(error=>onNotify(errorMessage(error),'error'))}>立即切换</button></>:selected==='authorOnly'?<SettingCheck label="阅读时只看楼主" checked={local.authorOnly} onChange={value=>setLocal({...local,authorOnly:value})}/>:selected==='block'?<><div className="inline-field"><input value={blockName} placeholder="用户名或 UID" aria-label="屏蔽用户名或UID" onChange={event=>setBlockName(event.target.value)}/><button className="primary-button" disabled={!blockName.trim()} onClick={()=>{const name=blockName.trim();setLocal({...local,blocked:[...local.blocked,{name,memberId:/^\d+$/.test(name)?Number(name):undefined}]});setBlockName('');}}>添加</button></div><div className="blocked-user-list">{local.blocked.map((user,index)=><div key={index}><Avatar name={user.name} id={user.memberId}/><span>{user.name}</span>{user.memberId&&<button className="text-button" onClick={()=>onMember(user.memberId!)}>资料</button>}<button className="text-button" onClick={()=>setLocal({...local,blocked:local.blocked.filter((_,i)=>i!==index)})}>解除屏蔽</button></div>)}</div></>:selected==='keywords'?<><label className="field-label">监控关键词<textarea value={local.watchWords} onChange={event=>setLocal({...local,watchWords:event.target.value})} placeholder="香港+CN2,美国+9929"/></label><p className="muted">同组词使用 + 同时匹配，不同组使用逗号分隔；仅监控启用后读取的新帖。</p><label className="field-label">备注<input value={local.watchNote} onChange={event=>setLocal({...local,watchNote:event.target.value})}/></label><SettingCheck label="系统通知" checked={local.watchSystemNotifications} onChange={value=>setLocal({...local,watchSystemNotifications:value})}/><p className="muted">最后检查 {state.lastCheck?dateLabel(state.lastCheck,true):'—'}{state.watchError&&` · ${state.watchError}`}</p><div className="keyword-hits">{state.hits.map(hit=><button className="activity-row" key={`${hit.post.id}-${hit.date}`} onClick={()=>{onOpenPost(hit.post);selectExtension(null);}}><Bell size={17}/><span><strong>{hit.post.title}</strong><small>{hit.words.join(' · ')} · {dateLabel(hit.date)}</small></span></button>)}</div></>:selected==='rulings'?<><div className="inline-field"><input value={uid} onChange={event=>setUid(event.target.value)} placeholder="输入用户名或 UID" aria-label="查询管理记录UID"/><button className="primary-button" disabled={querying||!uid.trim()} onClick={()=>{setQuerying(true);void window.seekdesk.queryRulings(/^\d+$/.test(uid)?Number(uid):0,/^\d+$/.test(uid)?undefined:uid.trim()).then(setRulings).catch(error=>onNotify(errorMessage(error),'error')).finally(()=>setQuerying(false));}}>查询</button></div>{querying?<Loading/>:rulings&&<div className="rulings-list">{rulings.records.length?rulings.records.map(record=><article key={record.id}><strong>{record.action}</strong><p>{record.reason}</p><small>{record.date}{record.operator&&` · ${record.operator}`}</small>{record.url&&<button className="text-button" onClick={()=>void window.seekdesk.openExternal(record.url!)}>查看原记录</button>}</article>):<Empty>未查询到公开管理记录</Empty>}</div>}</>:selected==='value'?<><p>使用你的剩余价值计算器。</p><a className="calculator-site-link" href="https://sy.3xme.com" onClick={event=>{event.preventDefault();void window.seekdesk.openCalculator().catch(error=>onNotify(errorMessage(error),'error'));}}>sy.3xme.com<ExternalLink size={15}/></a><button className="primary-button" onClick={()=>void window.seekdesk.openCalculator().catch(error=>onNotify(errorMessage(error),'error'))}>打开计算器<ArrowRight size={16}/></button></>:null}<div className="panel-actions"><button className="secondary-button" onClick={()=>selectExtension(null)}>关闭</button>{!['value','rulings'].includes(selected)&&<button className="primary-button" disabled={saving} onClick={()=>void save().then(saved=>{if(saved)onNotify('扩展配置已保存','success');})}><Save size={17}/>保存设置</button>}</div></Modal>}</section>;
}
function SettingCheck({label,checked,onChange}:{label:string;checked:boolean;onChange:(value:boolean)=>void}) {return <div className="setting-row"><strong>{label}</strong><button className={`toggle${checked?' checked':''}`} role="switch" aria-label={label} aria-checked={checked} onClick={()=>onChange(!checked)}><span/></button></div>;}

export function FriendsPanel({onBack}:{onBack:()=>void}) {
  return <section className="full-page"><PageHeading title="友情链接" onBack={onBack}/><div className="page-scroll friend-grid">
    <article className="friend-card"><img src="./assets/partner-impart.png" alt="Impart Logo"/><strong>Impart</strong><p>全球自建家宽测速，VPS与IDC、银行卡、电话卡交流与优惠。</p><div className="session-actions"><a className="text-button" href="https://t.me/Impart_Cloud" onClick={event=>{event.preventDefault();void window.seekdesk.openExternal('https://t.me/Impart_Cloud');}}>Telegram 群组<ExternalLink size={15}/></a></div></article>
    <article className="friend-card source-code-card"><span className="friend-source-icon"><Code2 size={28}/></span><strong>SeekDesk 原代码</strong><p>查看上游 SeekDesk 的源码、完整功能说明与项目文档。</p><div className="session-actions"><a className="text-button" href="https://github.com/cshaizhihao/SeekDesk/tree/main?tab=readme-ov-file" onClick={event=>{event.preventDefault();void window.seekdesk.openExternal('https://github.com/cshaizhihao/SeekDesk/tree/main?tab=readme-ov-file');}}>GitHub 原代码<ExternalLink size={15}/></a></div></article>
  </div></section>;
}
